'use strict';
// Draft generated by FreeLLMAPI (gpt-oss-20b via ovh); saved by Claude.

const asyncHandler = require('../utils/asyncHandler');
const {
  updateProfile: updateProfileValidator,
  usernameParams,
  updateSettings: updateSettingsValidator,
  searchQuery,
} = require('../validators/profileValidators');
const {
  getMyProfile,
  getProfileByUsername,
  updateProfile,
  getSettings,
  updateSettings,
  searchUsers,
} = require('../services/profileService');

function ok(res, data, status = 200) {
  return res.status(status).json({ success: true, data });
}

exports.me = asyncHandler(async (req, res) => {
  const profile = await getMyProfile(req.user.id);
  return ok(res, profile);
});

exports.byUsername = asyncHandler(async (req, res) => {
  const { username } = usernameParams.parse(req.params);
  const viewerId = req.user ? req.user.id : null;
  const profile = await getProfileByUsername(viewerId, username);
  return ok(res, profile);
});

exports.update = asyncHandler(async (req, res) => {
  const fields = updateProfileValidator.parse(req.body);
  const updated = await updateProfile(req.user.id, fields);
  return ok(res, updated);
});

exports.getSettings = asyncHandler(async (req, res) => {
  const settings = await getSettings(req.user.id);
  return ok(res, settings);
});

exports.updateSettings = asyncHandler(async (req, res) => {
  const fields = updateSettingsValidator.parse(req.body);
  const updated = await updateSettings(req.user.id, fields);
  return ok(res, updated);
});

exports.search = asyncHandler(async (req, res) => {
  const { q, limit } = searchQuery.parse(req.query);
  const viewerId = req.user ? req.user.id : null;
  const results = await searchUsers(viewerId, q, limit);
  return ok(res, results);
});
